//! Integer-ranked colour refinement with nested components: a blank-node
//! labelling with nested components.
//!
//! A measurement and attack module: nothing ships from it. LITERAL runs the
//! definition with no shortcut (naive synchronous rounds, every child of every
//! target cell). OPTIMISED adds worklist refinement, the single path on plain
//! incidence forests, twin classes and orbit pruning over the group generated by
//! the discovered automorphisms.
//!
//! A line is its masked text (`MARK` in each free blank position) and the ordered
//! tuple of its free blank nodes. Colours are cell offsets within one component.
//! After each refinement the nodes in singleton cells are fixed, become constants
//! in the text, and the remainder falls into free components, each labelled alone
//! and ordered by certificate. Nothing is hashed.

use std::cell::Cell;
use std::cmp::Ordering;
use std::fmt::Write as _;

use purrdf_core::FastMap;

/// A blank position in a line's text: a control character, which no spelled
/// constant contains. The masked text of the definition writes `_:` there.
pub(crate) const MARK: char = '\u{1}';

/// One counted canonical line.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) struct RawLine {
    pub(crate) text: String,
    pub(crate) tuple: Vec<u32>,
    pub(crate) count: u32,
}

/// Which computation of the definition to run.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Mode {
    Literal,
    Optimised,
}

/// How to run.
#[derive(Clone, Copy, Debug)]
pub(crate) struct Options {
    pub(crate) mode: Mode,
    /// Work units after which the run is refused.
    pub(crate) limit: u64,
    /// Optimised only: search forests by leaf minimum too (tests the forest claim).
    pub(crate) no_forest_path: bool,
    /// Optimised only: no orbit pruning (the unpruned optimised search).
    pub(crate) no_orbits: bool,
}

impl Options {
    pub(crate) const OPTIMISED: Self = Self {
        mode: Mode::Optimised,
        limit: u64::MAX,
        no_forest_path: false,
        no_orbits: false,
    };
    pub(crate) const LITERAL: Self = Self {
        mode: Mode::Literal,
        ..Self::OPTIMISED
    };
}

/// What the run did. A WORK UNIT is one occurrence visited when a signature is
/// formed, one certificate entry formed, or one certificate entry compared;
/// signature comparisons are counted apart.
#[derive(Clone, Debug, Default)]
pub(crate) struct Stats {
    pub(crate) nodes: usize,
    pub(crate) lines: usize,
    pub(crate) components: usize,
    pub(crate) residual_components: usize,
    pub(crate) largest_component: usize,
    pub(crate) root_nonsingleton_nodes: usize,
    pub(crate) root_largest_cell: usize,
    pub(crate) visits: u64,
    pub(crate) sig_compares: u64,
    pub(crate) cert_formed: u64,
    pub(crate) cert_compared: u64,
    pub(crate) rounds: u64,
    pub(crate) canon_calls: u64,
    pub(crate) children: u64,
    pub(crate) max_depth: u32,
    pub(crate) pruned_twin: u64,
    pub(crate) pruned_orbit: u64,
    pub(crate) forest_paths: u64,
    pub(crate) equal_leaves: u64,
}

impl Stats {
    pub(crate) fn units(&self) -> u64 {
        self.visits + self.cert_formed + self.cert_compared
    }
}

/// The work ceiling was reached; nothing is labelled.
#[derive(Debug)]
pub(crate) struct Refusal(pub(crate) Box<Stats>);

/// A finished labelling.
#[derive(Debug)]
pub(crate) struct Labelled {
    /// `(original node number, label number)`, by original number.
    pub(crate) labels: Vec<(u32, u32)>,
    pub(crate) document: String,
    pub(crate) stats: Stats,
}

struct Line {
    /// Text with `MARK` at each free occurrence and fixed nodes spelled as constants.
    text: String,
    trank: u32,
    tuple: Vec<u32>,
    count: u32,
}

/// One labelling problem: a connected set of free nodes numbered locally.
struct Prob {
    n: usize,
    lines: Vec<Line>,
    by_node: Vec<Vec<u32>>,
    /// The plain incidence graph (no merging of parallel lines) is acyclic.
    forest: bool,
    lookup: Option<FastMap<(u32, Vec<u32>), u32>>,
}

/// An ordered partition. A cell has an id, a start (its colour) and members;
/// ids are never reused, so a split never moves another cell's colour.
#[derive(Clone)]
struct Col {
    cell_of: Vec<u32>,
    pos: Vec<u32>,
    start: Vec<u32>,
    members: Vec<Vec<u32>>,
}

impl Col {
    fn new(n: usize) -> Self {
        Self {
            cell_of: vec![0; n],
            pos: (0..n as u32).collect(),
            start: vec![0],
            members: vec![(0..n as u32).collect()],
        }
    }

    fn colour(&self, v: u32) -> u32 {
        self.start[self.cell_of[v as usize] as usize]
    }

    fn discrete(&self) -> bool {
        self.cell_of.len() == self.live()
    }

    fn live(&self) -> usize {
        self.members.iter().filter(|m| !m.is_empty()).count()
    }

    fn new_cell(&mut self, start: u32) -> u32 {
        self.start.push(start);
        self.members.push(Vec::new());
        self.members.len() as u32 - 1
    }

    fn move_node(&mut self, v: u32, to: u32) {
        let from = self.cell_of[v as usize] as usize;
        let p = self.pos[v as usize] as usize;
        let last = *self.members[from].last().expect("a member");
        self.members[from].swap_remove(p);
        if last != v {
            self.pos[last as usize] = p as u32;
        }
        self.pos[v as usize] = self.members[to as usize].len() as u32;
        self.members[to as usize].push(v);
        self.cell_of[v as usize] = to;
    }

    /// The first non-singleton cell: the one of smallest colour.
    fn target(&self) -> Option<u32> {
        let mut best: Option<(usize, u32, u32)> = None;
        for (id, m) in self.members.iter().enumerate() {
            if m.len() > 1 {
                let key = (0, self.start[id]);
                if best.is_none_or(|(s, c, _)| key < (s, c)) {
                    best = Some((key.0, key.1, id as u32));
                }
            }
        }
        best.map(|b| b.2)
    }

    /// `v` keeps the cell's colour and the others take the next one. Returns the
    /// nodes whose colour changed.
    fn individualise(&mut self, v: u32) -> Vec<u32> {
        let x = self.cell_of[v as usize];
        let c = self.start[x as usize];
        let y = self.new_cell(c);
        self.move_node(v, y);
        self.start[x as usize] = c + 1;
        self.members[x as usize].clone()
    }

    fn from_colours(colours: &[u32]) -> Self {
        let n = colours.len();
        let mut order: Vec<u32> = (0..n as u32).collect();
        order.sort_by_key(|&v| (colours[v as usize], v));
        let mut col = Self {
            cell_of: vec![0; n],
            pos: vec![0; n],
            start: Vec::new(),
            members: Vec::new(),
        };
        let mut last = None;
        for v in order {
            let c = colours[v as usize];
            if last != Some(c) {
                col.new_cell(c);
                last = Some(c);
            }
            let id = col.members.len() as u32 - 1;
            col.pos[v as usize] = col.members[id as usize].len() as u32;
            col.members[id as usize].push(v);
            col.cell_of[v as usize] = id;
        }
        col
    }
}

type Cert = Vec<(u32, String, Vec<u32>)>;

struct Run<'a> {
    st: &'a mut Stats,
    limit: u64,
    opts: Options,
}

impl Run<'_> {
    fn check(&self) -> Result<(), ()> {
        if self.st.units() > self.limit {
            Err(())
        } else {
            Ok(())
        }
    }
}

fn cmp_cert(a: &Cert, b: &Cert, compared: &mut u64) -> Ordering {
    for (x, y) in a.iter().zip(b) {
        *compared += 1;
        match x.cmp(y) {
            Ordering::Equal => {}
            other => return other,
        }
    }
    a.len().cmp(&b.len())
}

fn mask(text: &str) -> String {
    text.replace(MARK, "_:")
}

impl Prob {
    fn new(n: usize, parts: Vec<(String, Vec<u32>, u32)>) -> Self {
        let masked: Vec<String> = parts.iter().map(|p| mask(&p.0)).collect();
        let mut texts: Vec<&str> = masked.iter().map(String::as_str).collect();
        texts.sort_unstable();
        texts.dedup();
        let lines: Vec<Line> = parts
            .into_iter()
            .zip(&masked)
            .map(|((text, tuple, count), m)| Line {
                text,
                trank: texts.binary_search(&m.as_str()).expect("a known text") as u32,
                tuple,
                count,
            })
            .collect();
        let mut by_node = vec![Vec::new(); n];
        let mut edges = 0;
        for (i, l) in lines.iter().enumerate() {
            let mut t = l.tuple.clone();
            t.sort_unstable();
            t.dedup();
            edges += t.len();
            for x in t {
                by_node[x as usize].push(i as u32);
            }
        }
        let forest = edges + 1 == n + lines.len();
        Self {
            n,
            lines,
            by_node,
            forest,
            lookup: None,
        }
    }

    fn sig(&self, col: &Col, v: u32, st: &mut Stats) -> Vec<u32> {
        let mut buf: Vec<u32> = Vec::new();
        let mut spans: Vec<(usize, usize)> = Vec::new();
        for &l in &self.by_node[v as usize] {
            let line = &self.lines[l as usize];
            for (p, &x) in line.tuple.iter().enumerate() {
                if x != v {
                    continue;
                }
                st.visits += 1;
                let start = buf.len();
                buf.push(line.trank);
                buf.push(p as u32);
                buf.extend(line.tuple.iter().map(|&y| col.colour(y)));
                for _ in 0..line.count {
                    spans.push((start, buf.len()));
                }
            }
        }
        let compares = Cell::new(0u64);
        spans.sort_by(|a, b| {
            compares.set(compares.get() + 1);
            buf[a.0..a.1].cmp(&buf[b.0..b.1])
        });
        st.sig_compares += compares.get();
        spans
            .iter()
            .flat_map(|&(a, b)| buf[a..b].iter().copied())
            .collect()
    }

    fn sort_by_sig(&self, sigs: &mut [(Vec<u32>, u32)], st: &mut Stats) {
        let compares = Cell::new(0u64);
        sigs.sort_by(|a, b| {
            compares.set(compares.get() + 1);
            a.0.cmp(&b.0).then(a.1.cmp(&b.1))
        });
        st.sig_compares += compares.get();
    }

    /// The definition's rounds, with no shortcut.
    fn refine_literal(&self, col: &mut Col, run: &mut Run<'_>) -> Result<(), ()> {
        loop {
            run.st.rounds += 1;
            let mut colours: Vec<u32> = (0..self.n as u32).map(|v| col.colour(v)).collect();
            let mut split = false;
            for id in 0..col.members.len() {
                let members = &col.members[id];
                if members.len() < 2 {
                    continue;
                }
                let mut sigs: Vec<(Vec<u32>, u32)> = members
                    .iter()
                    .map(|&v| (self.sig(col, v, run.st), v))
                    .collect();
                run.check()?;
                self.sort_by_sig(&mut sigs, run.st);
                let c = col.start[id];
                let mut offset = 0;
                let mut i = 0;
                while i < sigs.len() {
                    let mut j = i;
                    while j < sigs.len() && sigs[j].0 == sigs[i].0 {
                        j += 1;
                    }
                    for s in &sigs[i..j] {
                        colours[s.1 as usize] = c + offset;
                    }
                    if j - i < sigs.len() {
                        split = true;
                    }
                    offset += (j - i) as u32;
                    i = j;
                }
            }
            if !split {
                return Ok(());
            }
            *col = Col::from_colours(&colours);
        }
    }

    /// Worklist rounds: only nodes sharing a line with a node whose colour
    /// changed are re-evaluated, plus one untouched representative per cell.
    fn refine_worklist(
        &self,
        col: &mut Col,
        mut changed: Vec<u32>,
        stamp: &mut (Vec<u32>, u32),
        run: &mut Run<'_>,
    ) -> Result<(), ()> {
        struct Split {
            cell: u32,
            groups: Vec<(Vec<u32>, bool)>,
            implicit: usize,
        }
        while !changed.is_empty() {
            run.st.rounds += 1;
            stamp.1 += 1;
            let tag = stamp.1;
            let mut affected: Vec<u32> = Vec::new();
            for &c in &changed {
                for &l in &self.by_node[c as usize] {
                    for &x in &self.lines[l as usize].tuple {
                        if stamp.0[x as usize] != tag {
                            stamp.0[x as usize] = tag;
                            affected.push(x);
                        }
                    }
                }
            }
            affected.sort_unstable_by_key(|&x| (col.cell_of[x as usize], x));
            let mut splits: Vec<Split> = Vec::new();
            let mut at = 0;
            while at < affected.len() {
                let cell = col.cell_of[affected[at] as usize];
                let mut end = at;
                while end < affected.len() && col.cell_of[affected[end] as usize] == cell {
                    end += 1;
                }
                let chunk = &affected[at..end];
                at = end;
                let size = col.members[cell as usize].len();
                let mut sigs: Vec<(Vec<u32>, u32)> = chunk
                    .iter()
                    .map(|&x| (self.sig(col, x, run.st), x))
                    .collect();
                let mut implicit = 0;
                if chunk.len() < size {
                    let rep = *col.members[cell as usize]
                        .iter()
                        .find(|&&m| stamp.0[m as usize] != tag)
                        .expect("an unaffected member");
                    implicit = size - chunk.len();
                    sigs.push((self.sig(col, rep, run.st), u32::MAX));
                }
                run.check()?;
                self.sort_by_sig(&mut sigs, run.st);
                let mut groups: Vec<(Vec<u32>, bool)> = Vec::new();
                let mut last: Option<&Vec<u32>> = None;
                for (sig, x) in &sigs {
                    if last != Some(sig) {
                        groups.push((Vec::new(), false));
                        last = Some(sig);
                    }
                    let g = groups.last_mut().expect("a group");
                    if *x == u32::MAX {
                        g.1 = true;
                    } else {
                        g.0.push(*x);
                    }
                }
                if groups.len() > 1 {
                    splits.push(Split {
                        cell,
                        groups,
                        implicit,
                    });
                }
            }
            changed.clear();
            for s in splits {
                let c = col.start[s.cell as usize];
                let sizes: Vec<usize> = s
                    .groups
                    .iter()
                    .map(|g| g.0.len() + if g.1 { s.implicit } else { 0 })
                    .collect();
                let keeper = s.groups.iter().position(|g| g.1).unwrap_or(0);
                let mut offset = 0u32;
                let mut starts = Vec::with_capacity(sizes.len());
                for z in &sizes {
                    starts.push(c + offset);
                    offset += *z as u32;
                }
                for (gi, g) in s.groups.iter().enumerate() {
                    if gi == keeper {
                        continue;
                    }
                    let y = col.new_cell(starts[gi]);
                    for &v in &g.0 {
                        col.move_node(v, y);
                        if gi != 0 {
                            changed.push(v);
                        }
                    }
                }
                col.start[s.cell as usize] = starts[keeper];
                if keeper != 0 {
                    changed.extend(col.members[s.cell as usize].iter().copied());
                }
            }
            changed.sort_unstable();
        }
        Ok(())
    }

    fn certificate(&self, order: &[u32], base: u32, run: &mut Run<'_>) -> Cert {
        let mut pos = vec![0u32; self.n];
        for (i, &v) in order.iter().enumerate() {
            pos[v as usize] = base + i as u32;
        }
        let mut cert: Cert = Vec::new();
        for line in &self.lines {
            let p: Vec<u32> = line.tuple.iter().map(|&v| pos[v as usize]).collect();
            let m = p.iter().copied().max().unwrap_or(0);
            let entry = (m, mask(&line.text), p);
            for _ in 0..line.count {
                run.st.cert_formed += 1;
                cert.push(entry.clone());
            }
        }
        cert.sort_unstable();
        cert
    }

    fn twins(&mut self, u: u32, v: u32) -> bool {
        if self.lookup.is_none() {
            let mut map: FastMap<(u32, Vec<u32>), u32> = FastMap::default();
            for l in &self.lines {
                *map.entry((l.trank, l.tuple.clone())).or_default() += l.count;
            }
            self.lookup = Some(map);
        }
        let map = self.lookup.as_ref().expect("built");
        let mut ls: Vec<u32> = self.by_node[u as usize].clone();
        ls.extend(&self.by_node[v as usize]);
        ls.sort_unstable();
        ls.dedup();
        ls.into_iter().all(|l| {
            let line = &self.lines[l as usize];
            let swapped: Vec<u32> = line
                .tuple
                .iter()
                .map(|&x| {
                    if x == u {
                        v
                    } else if x == v {
                        u
                    } else {
                        x
                    }
                })
                .collect();
            map.get(&(line.trank, swapped)) == Some(&line.count)
        })
    }

    fn refine_any(
        &self,
        col: &mut Col,
        changed: Vec<u32>,
        stamp: &mut (Vec<u32>, u32),
        run: &mut Run<'_>,
    ) -> Result<(), ()> {
        if run.opts.mode == Mode::Optimised {
            self.refine_worklist(col, changed, stamp, run)
        } else {
            self.refine_literal(col, run)
        }
    }

    /// The root colouring: one cell, refined.
    fn root(&self, stamp: &mut (Vec<u32>, u32), run: &mut Run<'_>) -> Result<Col, ()> {
        let mut col = Col::new(self.n);
        self.refine_any(&mut col, (0..self.n as u32).collect(), stamp, run)?;
        Ok(col)
    }

    /// Label this problem alone: the minimal leaf as (certificate, nodes in position order).
    fn canon(&mut self, base: u32, depth: u32, run: &mut Run<'_>) -> Result<(Cert, Vec<u32>), ()> {
        run.st.canon_calls += 1;
        run.st.max_depth = run.st.max_depth.max(depth);
        if self.n == 1 {
            let order = vec![0];
            let cert = self.certificate(&order, base, run);
            return Ok((cert, order));
        }
        let mut stamp = (vec![0u32; self.n], 0u32);
        let root = self.root(&mut stamp, run)?;
        if depth == 0 && !root.discrete() {
            run.st.residual_components += 1;
            let sizes = root.members.iter().map(Vec::len).filter(|&s| s > 1);
            run.st.root_nonsingleton_nodes += sizes.clone().sum::<usize>();
            run.st.root_largest_cell = run.st.root_largest_cell.max(sizes.max().unwrap_or(0));
        }
        let optimised = run.opts.mode == Mode::Optimised;
        let (leaf_first, leaf_rest) = self.settle(&root, base, depth, run)?;
        if let Some(done) = leaf_first {
            return Ok(done);
        }
        // Branch on the first non-singleton cell of an undecomposable root.
        let cell = leaf_rest.expect("a branching root has a target");
        let mut cands = root.members[cell as usize].clone();
        cands.sort_unstable();
        if optimised && self.forest && !run.opts.no_forest_path {
            run.st.forest_paths += 1;
            cands.truncate(1);
        } else if optimised {
            let mut reps: Vec<u32> = Vec::new();
            for v in cands {
                if reps.iter().any(|&u| self.twins(u, v)) {
                    run.st.pruned_twin += 1;
                } else {
                    reps.push(v);
                }
            }
            cands = reps;
        }
        let orbits_on = optimised && !run.opts.no_orbits;
        fn find(m: &FastMap<u32, u32>, x: u32) -> u32 {
            let mut r = x;
            while let Some(&p) = m.get(&r) {
                if p == r {
                    break;
                }
                r = p;
            }
            r
        }
        let mut orbit: FastMap<u32, u32> = FastMap::default();
        let mut tried: Vec<u32> = Vec::new();
        let mut first: Option<(Cert, Vec<u32>)> = None;
        let mut best: Option<(Cert, Vec<u32>)> = None;
        for v in cands {
            if orbits_on {
                let rv = find(&orbit, v);
                if tried.iter().any(|&u| find(&orbit, u) == rv) {
                    run.st.pruned_orbit += 1;
                    continue;
                }
            }
            tried.push(v);
            run.st.children += 1;
            let mut child = root.clone();
            let changed = child.individualise(v);
            self.refine_any(&mut child, changed, &mut stamp, run)?;
            let (done, _) = self.settle(&child, base, depth, run)?;
            let leaf = done.expect("a child decomposes: its individualised node is fixed");
            let mut c = 0;
            let against = best.as_ref().map(|b| cmp_cert(&leaf.0, &b.0, &mut c));
            run.st.cert_compared += c;
            run.st.equal_leaves += u64::from(against == Some(Ordering::Equal));
            if orbits_on {
                // An equal certificate is an automorphism (position-wise); merge its orbits.
                let mut equal_to: Vec<&(Cert, Vec<u32>)> = Vec::new();
                if against == Some(Ordering::Equal) {
                    equal_to.extend(best.as_ref());
                }
                if let Some(f) = first.as_ref() {
                    let mut c2 = 0;
                    let eq = cmp_cert(&leaf.0, &f.0, &mut c2) == Ordering::Equal;
                    run.st.cert_compared += c2;
                    if eq && !equal_to.iter().any(|o| std::ptr::eq(*o, f)) {
                        equal_to.push(f);
                    }
                }
                for other in equal_to {
                    for (&a, &b) in other.1.iter().zip(&leaf.1) {
                        let (ra, rb) = (find(&orbit, a), find(&orbit, b));
                        if ra != rb {
                            orbit.insert(ra, rb);
                        }
                    }
                }
            }
            if first.is_none() {
                first = Some(leaf.clone());
            }
            if against.is_none_or(|o| o == Ordering::Less) {
                best = Some(leaf);
            }
        }
        best.ok_or(())
    }

    /// Fix the singleton cells of a refined colouring in colour order, split the
    /// remainder into free components and label each alone. Returns the leaf when
    /// the colouring decomposes (some node fixed, or several components); otherwise
    /// `None` and the target cell to branch on.
    #[allow(clippy::type_complexity)]
    fn settle(
        &self,
        col: &Col,
        base: u32,
        depth: u32,
        run: &mut Run<'_>,
    ) -> Result<(Option<(Cert, Vec<u32>)>, Option<u32>), ()> {
        let mut cells: Vec<(u32, u32)> = col
            .members
            .iter()
            .enumerate()
            .filter(|(_, m)| !m.is_empty())
            .map(|(id, _)| (col.start[id], id as u32))
            .collect();
        cells.sort_unstable();
        let singles: Vec<u32> = cells
            .iter()
            .filter(|c| col.members[c.1 as usize].len() == 1)
            .map(|c| col.members[c.1 as usize][0])
            .collect();
        let rest: Vec<u32> = cells
            .iter()
            .filter(|c| col.members[c.1 as usize].len() > 1)
            .flat_map(|c| col.members[c.1 as usize].iter().copied())
            .collect();
        if rest.is_empty() {
            let cert = self.certificate(&singles, base, run);
            return Ok((Some((cert, singles)), None));
        }
        // Free components of the remainder: nodes joined by a line.
        let mut comp_of = vec![u32::MAX; self.n];
        let mut loc = vec![0u32; self.n];
        let mut comps: Vec<Vec<u32>> = Vec::new();
        let mut sorted_rest = rest.clone();
        sorted_rest.sort_unstable();
        let in_rest: Vec<bool> = {
            let mut m = vec![false; self.n];
            for &v in &rest {
                m[v as usize] = true;
            }
            m
        };
        for &s in &sorted_rest {
            if comp_of[s as usize] != u32::MAX {
                continue;
            }
            let id = comps.len() as u32;
            comp_of[s as usize] = id;
            let mut members = vec![s];
            let mut at = 0;
            while at < members.len() {
                let v = members[at];
                at += 1;
                for &l in &self.by_node[v as usize] {
                    for &x in &self.lines[l as usize].tuple {
                        if in_rest[x as usize] && comp_of[x as usize] == u32::MAX {
                            comp_of[x as usize] = id;
                            members.push(x);
                        }
                    }
                }
            }
            members.sort_unstable();
            for (i, &v) in members.iter().enumerate() {
                loc[v as usize] = i as u32;
            }
            comps.push(members);
        }
        if singles.is_empty() && comps.len() == 1 {
            return Ok((None, col.target()));
        }
        let mut pos = vec![u32::MAX; self.n];
        for (i, &v) in singles.iter().enumerate() {
            pos[v as usize] = base + i as u32;
        }
        let mut parts: Vec<Vec<(String, Vec<u32>, u32)>> = vec![Vec::new(); comps.len()];
        for line in &self.lines {
            let Some(&first_free) = line
                .tuple
                .iter()
                .find(|&&u| comp_of[u as usize] != u32::MAX)
            else {
                continue;
            };
            let k = comp_of[first_free as usize];
            let mut text = String::with_capacity(line.text.len() + 8);
            let mut tuple = Vec::new();
            let mut occ = line.tuple.iter();
            for ch in line.text.chars() {
                if ch == MARK {
                    let u = *occ.next().expect("a node for every mask");
                    if comp_of[u as usize] == k {
                        text.push(MARK);
                        tuple.push(loc[u as usize]);
                    } else {
                        let _ = write!(text, "_:{}", pos[u as usize]);
                    }
                } else {
                    text.push(ch);
                }
            }
            parts[k as usize].push((text, tuple, line.count));
        }
        let mut results: Vec<(Cert, Vec<u32>, usize)> = Vec::new();
        for (k, p) in parts.into_iter().enumerate() {
            let mut sub = Self::new(comps[k].len(), p);
            let (cert, order) = sub.canon(base + singles.len() as u32, depth + 1, run)?;
            results.push((cert, order, k));
        }
        let mut compared = 0;
        results.sort_by(|a, b| cmp_cert(&a.0, &b.0, &mut compared));
        run.st.cert_compared += compared;
        let mut order = singles;
        for (_, local_order, k) in &results {
            order.extend(local_order.iter().map(|&i| comps[*k][i as usize]));
        }
        let cert = self.certificate(&order, base, run);
        Ok((Some((cert, order)), None))
    }
}

/// The colour of every node after individualising `v` in the whole fold's first
/// refinement (one global partition), by the literal rounds.
pub(crate) fn global_individualised(input: &[RawLine], v: u32) -> Vec<(u32, u32)> {
    let (prob, ids) = whole(input);
    let mut stats = Stats::default();
    let mut run = Run {
        st: &mut stats,
        limit: u64::MAX,
        opts: Options::LITERAL,
    };
    let mut stamp = (vec![0u32; prob.n], 0u32);
    let mut col = prob.root(&mut stamp, &mut run).expect("no limit");
    let local = ids.iter().position(|&x| x == v).expect("a known node") as u32;
    let changed = col.individualise(local);
    prob.refine_any(&mut col, changed, &mut stamp, &mut run)
        .expect("no limit");
    let mut out: Vec<(u32, u32)> = ids
        .iter()
        .enumerate()
        .map(|(i, &x)| (x, col.colour(i as u32)))
        .collect();
    out.sort_unstable();
    out
}

/// The root colour of every node, by literal or worklist rounds.
pub(crate) fn root_colours(input: &[RawLine], optimised: bool) -> Vec<(u32, u32)> {
    let (prob, ids) = whole(input);
    let mut stats = Stats::default();
    let mut run = Run {
        st: &mut stats,
        limit: u64::MAX,
        opts: if optimised {
            Options::OPTIMISED
        } else {
            Options::LITERAL
        },
    };
    let mut stamp = (vec![0u32; prob.n], 0u32);
    let col = prob.root(&mut stamp, &mut run).expect("no limit");
    let mut out: Vec<(u32, u32)> = ids
        .iter()
        .enumerate()
        .map(|(i, &x)| (x, col.colour(i as u32)))
        .collect();
    out.sort_unstable();
    out
}

/// The whole fold as one problem (no components), with the node numbers it used.
fn whole(input: &[RawLine]) -> (Prob, Vec<u32>) {
    let (lines, dense, ids) = prepare(input);
    let parts = lines
        .iter()
        .filter(|l| !l.tuple.is_empty())
        .map(|l| {
            (
                l.text.clone(),
                l.tuple.iter().map(|t| dense[t]).collect(),
                l.count,
            )
        })
        .collect();
    (Prob::new(ids.len(), parts), ids)
}

type Prepared = (Vec<RawLine>, FastMap<u32, u32>, Vec<u32>);

/// Equal lines merged by adding their counts, nodes numbered densely by first use.
fn prepare(input: &[RawLine]) -> Prepared {
    let mut sorted: Vec<RawLine> = input.to_vec();
    sorted.sort_unstable_by(|a, b| (&a.text, &a.tuple).cmp(&(&b.text, &b.tuple)));
    let mut lines: Vec<RawLine> = Vec::new();
    for l in sorted {
        match lines.last_mut() {
            Some(p) if p.text == l.text && p.tuple == l.tuple => p.count += l.count,
            _ => lines.push(l),
        }
    }
    let mut dense: FastMap<u32, u32> = FastMap::default();
    let mut ids: Vec<u32> = Vec::new();
    for l in &lines {
        for &v in &l.tuple {
            dense.entry(v).or_insert_with(|| {
                ids.push(v);
                ids.len() as u32 - 1
            });
        }
    }
    (lines, dense, ids)
}

/// Label every blank node of `input`.
pub(crate) fn label(input: &[RawLine], opts: Options) -> Result<Labelled, Refusal> {
    let (all_lines, dense, ids) = prepare(input);
    // Lines with no blank node take no part in the labelling but are in the document.
    let (lines, ground): (Vec<RawLine>, Vec<RawLine>) =
        all_lines.into_iter().partition(|l| !l.tuple.is_empty());
    let n = ids.len();
    let mut stats = Stats {
        lines: lines.len(),
        nodes: n,
        ..Stats::default()
    };
    // Top-level components of the fold, each labelled alone.
    let mut parent: Vec<u32> = (0..n as u32).collect();
    fn find(p: &mut [u32], mut x: u32) -> u32 {
        while p[x as usize] != x {
            p[x as usize] = p[p[x as usize] as usize];
            x = p[x as usize];
        }
        x
    }
    for l in &lines {
        let first = dense[&l.tuple[0]];
        for t in &l.tuple[1..] {
            let (a, b) = (find(&mut parent, first), find(&mut parent, dense[t]));
            if a != b {
                parent[a as usize] = b;
            }
        }
    }
    let mut comp_of_root: FastMap<u32, usize> = FastMap::default();
    let mut members: Vec<Vec<u32>> = Vec::new();
    for v in 0..n as u32 {
        let r = find(&mut parent, v);
        let c = *comp_of_root.entry(r).or_insert_with(|| {
            members.push(Vec::new());
            members.len() - 1
        });
        members[c].push(v);
    }
    let mut loc = vec![0u32; n];
    for m in &members {
        for (i, &v) in m.iter().enumerate() {
            loc[v as usize] = i as u32;
        }
    }
    let mut parts: Vec<Vec<(String, Vec<u32>, u32)>> = vec![Vec::new(); members.len()];
    for l in &lines {
        let k = comp_of_root[&find(&mut parent, dense[&l.tuple[0]])];
        parts[k].push((
            l.text.clone(),
            l.tuple.iter().map(|t| loc[dense[t] as usize]).collect(),
            l.count,
        ));
    }
    stats.components = members.len();
    stats.largest_component = members.iter().map(Vec::len).max().unwrap_or(0);
    let mut results: Vec<(Cert, Vec<u32>, usize)> = Vec::new();
    let mut failed = false;
    {
        let mut run = Run {
            st: &mut stats,
            limit: opts.limit,
            opts,
        };
        for (k, p) in parts.into_iter().enumerate() {
            let mut prob = Prob::new(members[k].len(), p);
            match prob.canon(0, 0, &mut run) {
                Ok((cert, order)) => results.push((cert, order, k)),
                Err(()) => {
                    failed = true;
                    break;
                }
            }
        }
    }
    if failed {
        return Err(Refusal(Box::new(stats)));
    }
    let mut compared = 0;
    results.sort_by(|a, b| cmp_cert(&a.0, &b.0, &mut compared));
    stats.cert_compared += compared;
    let mut label_of = vec![0u32; n];
    let mut next = 0;
    for (_, order, k) in &results {
        for &local in order {
            label_of[members[*k][local as usize] as usize] = next;
            next += 1;
        }
    }
    let mut labels: Vec<(u32, u32)> = ids
        .iter()
        .enumerate()
        .map(|(i, &orig)| (orig, label_of[i]))
        .collect();
    labels.sort_unstable();
    let mut doc_lines: Vec<String> = lines
        .iter()
        .map(|l| {
            let mut out = String::with_capacity(l.text.len() + 8 * l.tuple.len());
            let mut it = l.tuple.iter();
            for ch in l.text.chars() {
                if ch == MARK {
                    let node = it.next().expect("a node for every mask");
                    out.push_str("_:c14n");
                    out.push_str(&label_of[dense[node] as usize].to_string());
                } else {
                    out.push(ch);
                }
            }
            out
        })
        .collect();
    doc_lines.extend(ground.into_iter().map(|l| l.text));
    doc_lines.sort_unstable();
    let mut document = String::new();
    for l in doc_lines {
        document.push_str(&l);
        document.push('\n');
    }
    Ok(Labelled {
        labels,
        document,
        stats,
    })
}
